  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:28', 'OLA2_CP_2017_01:CODIGO_PENAL:103', 'OLA2_CP_2017_01:CODIGO_PENAL:104', 'OLA2_CP_2017_01:CODIGO_PENAL:105', 'OLA2_CP_2017_01:CODIGO_PENAL:106', 'OLA2_CP_2017_01:CODIGO_PENAL:153', 'OLA2_CP_2017_01:CODIGO_PENAL:176', 'OLA2_CP_2017_01:CODIGO_PENAL:182', 'OLA2_CP_2017_01:CODIGO_PENAL:225', 'OLA2_CP_2017_01:CODIGO_PENAL:263', 'OLA2_CP_2017_01:CODIGO_PENAL:275', 'OLA2_CP_2017_01:CODIGO_PENAL:296', 'OLA2_CP_2017_01:CODIGO_PENAL:309', 'OLA2_CP_2017_01:CODIGO_PENAL:317', 'OLA2_CP_2017_01:CODIGO_PENAL:337', 'OLA2_CP_2017_01:CODIGO_PENAL:346', 'OLA2_CP_2017_01:CODIGO_PENAL:353', 'OLA2_CP_2017_01:CODIGO_PENAL:368', 'OLA2_CP_2017_01:CODIGO_PENAL:397', 'OLA2_CP_2017_01:CODIGO_PENAL:403', 'OLA2_CP_2017_01:CODIGO_PENAL:411', 'OLA2_CP_2017_01:CODIGO_PENAL:417', 'OLA2_CP_2017_01:CODIGO_PENAL:430', 'OLA2_CP_2017_01:CODIGO_PENAL:434', 'OLA2_CP_2017_01:CODIGO_PENAL:437', 'OLA2_CP_2017_01:CODIGO_PENAL:469', 'OLA2_CP_2017_01:CODIGO_PENAL:511', 'OLA2_CP_2017_01:CODIGO_PENAL:569', 'OLA2_CP_2017_01:CODIGO_PENAL:596', 'OLA2_CP_2017_01:CODIGO_PENAL:613');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY: texto oficial consolidado con D.43-2023 (La Gaceta)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CP_OLA2.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA2')
  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:102', 'OLA2_CP_2017_01:CODIGO_PENAL:444', 'OLA2_CP_2017_01:CODIGO_PENAL:587-A');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY: texto oficial consolidado con D.93-2021 (La Gaceta)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CP_OLA2.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA2')
  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:219', 'OLA2_CP_2017_01:CODIGO_PENAL:248', 'OLA2_CP_2017_01:CODIGO_PENAL:312', 'OLA2_CP_2017_01:CODIGO_PENAL:373', 'OLA2_CP_2017_01:CODIGO_PENAL:374', 'OLA2_CP_2017_01:CODIGO_PENAL:378', 'OLA2_CP_2017_01:CODIGO_PENAL:378-A', 'OLA2_CP_2017_01:CODIGO_PENAL:379', 'OLA2_CP_2017_01:CODIGO_PENAL:386', 'OLA2_CP_2017_01:CODIGO_PENAL:428', 'OLA2_CP_2017_01:CODIGO_PENAL:429');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY: texto oficial consolidado con D.59-2024 (La Gaceta)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CP_OLA2.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA2')
  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:324', 'OLA2_CP_2017_01:CODIGO_PENAL:327', 'OLA2_CP_2017_01:CODIGO_PENAL:337-A');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'CONTEXT vigente por dictamen del CLO (D5, 2026-11-24): lectura literal por sustitución integral del precepto en el D.59-2024 (Gaceta 36,595); suprimidos los dos párrafos añadidos por el D.93-2021 (constancia SUPRESION_POR_SUSTITUCION)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CP_OLA2.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA2')
  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:325');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY por dictamen del CLO (D5, 2026-11-24): epígrafe actualizado «EXÓGENAS» por el D.93-2021 (Gaceta 35,760); cuerpo de la Gaceta 34,940 sin cambios', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CP_OLA2.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA2')
  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:328');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY: texto oficial consolidado con D.93-2021, D.43-2023 (La Gaceta)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CP_OLA2.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA2')
  WHERE ingest_batch = 'OLA2_CP_2017_01' AND id IN ('OLA2_CP_2017_01:CODIGO_PENAL:439');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 638 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 638)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 607 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 607)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 1 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 1)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 30 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 30)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
  UPDATE public.biblioteca_vectores b SET revision_pendiente = true,
    metadata = b.metadata || jsonb_build_object('sustituido_por_lote', 'OLA2_CP_2017_01', 'sustituido_fecha', '2026-11-24', 'revision_pendiente_motivo', 'Sustituida por HN:CODIGO_PENAL V5 (OLA2); oculta, no borrada')
  WHERE b.metadata->>'norm_id' = 'HN_CODIGO_PENAL' AND b.id LIKE 'v2penal:mayalex_normativos:%' AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 635 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 635)', n; END IF;
END $do$;
COMMIT;
SELECT count(*) AS filas, count(*) FILTER (WHERE revision_pendiente = false) AS visibles, metadata->>'estado_v' AS estado_v,
  count(*) FILTER (WHERE es_norma_vigente = true AND NOT (metadata ? 'rol')) AS primary_vigentes,
  count(*) FILTER (WHERE metadata->>'rol' = 'CONTEXT') AS context,
  count(*) FILTER (WHERE es_norma_vigente = false) AS derogados,
  count(*) FILTER (WHERE embedding IS NOT NULL) AS con_embedding,
  count(*) FILTER (WHERE encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido) AS sha_ok
FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA2_CP_2017_01' GROUP BY metadata->>'estado_v';
